mapper.select:
SELECT -- 原 EmergencyPlan 字段，添加 plan_ 前缀别名，对应VO的 planXXX 字段 ep.id AS plan_id, ep.plan_name AS plan_name, ep.plan_type AS plan_type, ep.plan_desc AS plan_desc, ep.plan_doc AS plan_doc, ep.plan_status AS plan_status, ep.bpmn_xml AS bpmn_xml, ep.camera_ids AS camera_ids, ep.create_time AS plan_create_time, ep.update_time AS plan_update_time, ep.is_deleted AS plan_is_deleted,
-- 原 EmergencyPlanFlowRel 字段，添加 rel_ 前缀别名，对应VO的 relXXX 字段 epfr.id AS rel_id, epfr.plan_id AS rel_plan_id, epfr.deploy_id AS deploy_id, epfr.cur_proc_inst_id AS cur_proc_inst_id, epfr.current_task_id AS current_task_id, epfr.current_task_name AS current_task_name, epfr.flow_status AS flow_status, epfr.create_time AS rel_create_time, epfr.update_time AS rel_update_time, epfr.is_deleted AS rel_is_deleted
FROM public.emergency_plan ep LEFT JOIN public.emergency_plan_flow_rel epfr ON ep.id = epfr.plan_id AND epfr.is_deleted = 0 WHERE 1=1
AND ep.id = #{planDTO.id}
AND ep.plan_name LIKE CONCAT('%', #{planDTO.planName}, '%')
AND ep.plan_type = #{planDTO.planType}
AND ep.plan_status = #{planDTO.planStatus}
-- 逻辑删除过滤：只查询plan未删除的数据 AND ep.is_deleted = 0 ORDER BY ep.create_time DESC;
